"""mpl_toolkits.axes_grid1.axes_grid — grid of axes."""


class Grid:
    """nrows × ncols grid of axes laid out inside a figure rectangle.
    The shim creates each axes via ``fig.add_subplot`` and exposes the
    full upstream surface — indexed access, row/column views, axes_all."""

    def __init__(self, fig, rect, nrows_ncols, ngrids=None, direction='row',
                 axes_pad=0.02, *, share_all=False, share_x=True, share_y=True,
                 label_mode='L', axes_class=None, aspect=False):
        self.nrows, self.ncols = nrows_ncols
        self.ngrids = ngrids if ngrids is not None else self.nrows * self.ncols
        self.direction = direction
        self.axes_pad = (axes_pad, axes_pad) if isinstance(axes_pad, (int, float)) \
                          else tuple(axes_pad)
        self.share_all = bool(share_all)
        self.share_x = bool(share_x)
        self.share_y = bool(share_y)
        self.label_mode = label_mode
        self.aspect = aspect
        self._axes = []
        # Actually allocate the per-cell axes via the parent figure.
        if fig is not None and hasattr(fig, 'add_subplot'):
            for i in range(self.ngrids):
                row = i // self.ncols + 1
                col = i % self.ncols + 1
                try:
                    ax = fig.add_subplot(self.nrows, self.ncols, i + 1)
                    self._axes.append(ax)
                except Exception:
                    pass

    def __getitem__(self, i):
        return self._axes[i] if 0 <= i < len(self._axes) else None

    def __len__(self):
        return len(self._axes)

    def __iter__(self):
        return iter(self._axes)

    @property
    def axes_all(self):
        return list(self._axes)

    @property
    def axes_column(self):
        """Column-major view: ``axes_column[c]`` is the list of axes
        in column c, top-to-bottom."""
        cols = [[] for _ in range(self.ncols)]
        for i, ax in enumerate(self._axes):
            cols[i % self.ncols].append(ax)
        return cols

    @property
    def axes_row(self):
        """Row-major view: ``axes_row[r]`` is the list of axes in row r,
        left-to-right."""
        rows = [[] for _ in range(self.nrows)]
        for i, ax in enumerate(self._axes):
            rows[i // self.ncols].append(ax)
        return rows

    def get_geometry(self):
        return self.nrows, self.ncols

    def set_label_mode(self, mode):
        self.label_mode = mode

    def get_label_mode(self):
        return self.label_mode

    def set_axes_pad(self, padding):
        self.axes_pad = padding if isinstance(padding, tuple) \
                          else (padding, padding)

    def get_axes_pad(self):
        return self.axes_pad

    def set_aspect(self, aspect):
        self.aspect = aspect


class ImageGrid(Grid):
    """Grid variant that adds optional colorbar axes. ``cbar_mode``
    can be ``None`` / ``'each'`` / ``'single'`` / ``'edge'`` matching
    upstream."""

    def __init__(self, fig, rect, nrows_ncols, ngrids=None, direction='row',
                 axes_pad=0.02, *, share_all=False, aspect=True,
                 label_mode='L', cbar_mode=None, cbar_location='right',
                 cbar_pad=None, cbar_size='5%', cbar_set_cax=True,
                 axes_class=None):
        super().__init__(fig, rect, nrows_ncols, ngrids, direction, axes_pad,
                          share_all=share_all, aspect=aspect,
                          label_mode=label_mode, axes_class=axes_class)
        self.cbar_mode = cbar_mode
        self.cbar_location = cbar_location
        self.cbar_pad = cbar_pad
        self.cbar_size = cbar_size
        # Allocate colorbar axes alongside each cell when requested.
        self.cbar_axes = []
        if cbar_mode and fig is not None and hasattr(fig, 'add_subplot'):
            count = (len(self._axes) if cbar_mode == 'each'
                     else 1 if cbar_mode in ('single', 'edge') else 0)
            for i in range(count):
                try:
                    self.cbar_axes.append(fig.add_subplot(self.nrows, self.ncols, 1))
                except Exception:
                    pass


AxesGrid = ImageGrid


# ─── Added: CbarAxes and CbarAxesBase ───────────────────────────────


class CbarAxes:
    """Axes specialised for a colorbar — sits alongside an axes-grid
    cell and owns the colorbar's tick/label artists. The shim doesn't
    need a real subclass since the plotly backend draws colorbars via
    plotly's coloraxis."""

    orientation = 'vertical'

    def __init__(self, *args, **kwargs):
        self.orientation = kwargs.get('orientation', 'vertical')


class CbarAxesBase:
    """Mixin providing colorbar-specific accessors used by colorbar
    axes inside an axes_grid layout. Pairs with the regular axes
    class via :func:`cbaraxes_class_factory`."""

    orientation = 'vertical'

    def colorbar(self, mappable, **kwargs):
        return None

    def cla(self):
        pass

    def toggle_label(self, b):
        pass
